import {loadCatalog,galleries,make} from './site.js';
import {decodeArray,sha256,pixelToSky} from './science.js';
import {defaultVisualization,displayLevel,paletteRGB,validateVisualization} from './visualization.js';
const $=id=>document.getElementById(id);
const state={catalog:null,field:null,product:null,arrays:null,visual:{...defaultVisualization},zoom:1,cx:0,cy:0,contrast:1,request:0};
let source=null;
function facts(){const p=state.product,o=p.observation,items=[['Exposure start (UTC)',o.time_start_utc],['Exposure end (UTC)',o.time_end_utc],['Spectral range in usable field',p.wavelength_range_um.map(x=>x.toFixed(4)).join('–')+' μm'],['At the field center',`λ ${o.center_wavelength_um.toFixed(4)} μm · bandwidth ${o.center_bandwidth_um.toFixed(4)} μm`],['Release / detector / pipeline',`${o.release.toUpperCase()} / D${o.detector} / ${o.pipeline_version}`],['Native cutout',`${p.native_shape[1]} × ${p.native_shape[0]} pixels`],['Prepared context',`${p.shape[1]} × ${p.shape[0]} · ${p.pixel_scale_arcsec} arcsec/pixel`],['Usable context pixels',(100*state.arrays.VALID.reduce((a,b)=>a+b,0)/state.arrays.VALID.length).toFixed(1)+'%'],['Center (ICRS)',`${state.field.ra_deg.toFixed(5)}°, ${state.field.dec_deg.toFixed(5)}°`]];$('explore-facts').replaceChildren();for(const [k,v]of items){const row=make('div');row.append(make('dt',k),make('dd',v));$('explore-facts').append(row);}$('explore-source').replaceChildren();for(const [label,f]of [['Original FITS',o.source],['Full spectral calibration',o.spectral_calibration]]){const row=make('div',undefined,'source-row');row.append(make('strong',label),make('code',f.path),make('code','SHA-256 '+f.sha256));const a=make('a','Open original NASA/IPAC source ↗');a.href=f.source_url;a.target='_blank';a.rel='noreferrer';row.append(a);$('explore-source').append(row);}$('explore-source').append(make('p','Conservative flag mask: SOURCE alone retained. Unknown or other declared flags masked; every bilinear contributor must be usable. No temporal comparison is implied.'));}
function render(){if(!state.product)return;const [h,w]=state.product.shape,p=state.product,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d'),im=ctx.createImageData(w,h);const display={...p.display,vmax:p.display.vmin+(p.display.vmax-p.display.vmin)/state.contrast};for(let i=0;i<w*h;i++){const rgb=state.arrays.VALID[i]?paletteRGB(displayLevel(state.arrays.SCI[i],display,state.visual),state.visual.palette):[20,33,51];im.data.set([...rgb,255],i*4);}ctx.putImageData(im,0,0);source=canvas;draw();}
function geometry(){const rect=$('explore-canvas').getBoundingClientRect(),[h,w]=state.product.shape;return {width:rect.width,height:rect.height,scale:Math.min(rect.width/w,rect.height/h)*state.zoom};}
function draw(){if(!source)return;const c=$('explore-canvas'),g=geometry(),dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(g.width*dpr);c.height=Math.round(g.height*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#030710';ctx.fillRect(0,0,g.width,g.height);ctx.save();ctx.translate(g.width/2,g.height/2);ctx.scale(g.scale,-g.scale);ctx.imageSmoothingEnabled=state.visual.interpolation==='smooth';ctx.imageSmoothingQuality='high';ctx.drawImage(source,-state.cx-.5,-state.cy-.5); // Masks stay nearest sampled, even when the image is smoothly displayed.
  const [h,w]=state.product.shape;ctx.fillStyle='#142133';for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(!state.arrays.VALID[y*w+x])ctx.fillRect(x-state.cx-.5,y-state.cy-.5,1,1);ctx.restore();ctx.font='11px Consolas,monospace';ctx.fillStyle='#cbd9f4';ctx.fillText('N ↑',g.width-45,26);ctx.fillText('E ←',g.width-45,44);$('explore-zoom').textContent=state.zoom.toFixed(1)+'×';}
function setZoom(z){state.zoom=Math.max(1,Math.min(20,z));draw();}
async function selectObservation(entry,index){const seq=++state.request;$('explore-error').hidden=true;$('export-context').disabled=true;try{const r=await fetch(entry.url);if(!r.ok)throw Error('Observation data could not be loaded from the local server.');const bytes=new Uint8Array(await r.arrayBuffer());if(await sha256(bytes)!==entry.sha256)throw Error('Observation checksum mismatch; this view was not opened.');if(seq!==state.request)return;const p=JSON.parse(new TextDecoder().decode(bytes));if(p.dataset_kind!=='real'||p.usage!=='single_observation_only'||p.scientific_approval!=='PENDING')throw Error('Unsupported context identity');state.product=p;state.arrays=Object.fromEntries(Object.entries(p.arrays).map(([k,v])=>[k,decodeArray(v)]));state.zoom=1;state.cx=(p.shape[1]-1)/2;state.cy=(p.shape[0]-1)/2;state.contrast=1;$('explore-contrast').value=1;state.entry=entry;for(const [i,b]of [...$('observation-timeline').children].entries()){b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index));}facts();render();$('export-context').disabled=false;}catch(e){if(seq!==state.request)return;state.product=null;source=null;const c=$('explore-canvas');c.getContext('2d').clearRect(0,0,c.width,c.height);$('explore-error').hidden=false;$('explore-error').textContent=e.message;}}
function choose(id){const f=state.catalog.fields.find(f=>f.id===id)||state.catalog.fields[0];state.field=f;$('explore-title').textContent=f.title;$('explore-description').textContent=f.description;$('compare-link').hidden=f.id!=='m101';$('explore-status').textContent=f.id==='m101'?'Larger context: single exposure only. The 2.4-arcminute temporal review field is available separately; scientific approval remains PENDING.':'Single-exposure inspection only. All tested wider temporal pairs failed the wavelength screen. No supported temporal comparison is available.';$('observation-timeline').replaceChildren();for(const [i,o]of f.observations.entries()){const b=make('button',o.time_start_utc.slice(0,10)+' · '+o.time_start_utc.slice(11,19)+' UTC');b.title='View this individual exposure; not an A/B comparison';b.addEventListener('click',()=>selectObservation(o,i));$('observation-timeline').append(b);}selectObservation(f.observations[0],0);}
const canvas=$('explore-canvas');let drag=null;canvas.addEventListener('pointerdown',e=>{if(!state.product)return;canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,cx:state.cx,cy:state.cy};});canvas.addEventListener('pointermove',e=>{if(!state.product)return;const g=geometry(),rect=canvas.getBoundingClientRect(),[h,w]=state.product.shape;if(drag){state.cx=Math.max(0,Math.min(w-1,drag.cx-(e.clientX-drag.x)/g.scale));state.cy=Math.max(0,Math.min(h-1,drag.cy+(e.clientY-drag.y)/g.scale));draw();}const x=(e.clientX-rect.left-g.width/2)/g.scale+state.cx,y=-(e.clientY-rect.top-g.height/2)/g.scale+state.cy,ix=Math.round(x),iy=Math.round(y);if(ix<0||iy<0||ix>=w||iy>=h){$('explore-coordinate').textContent='Outside the prepared context.';return;}const i=iy*w+ix,sky=pixelToSky(ix,iy,state.product.wcs),valid=state.arrays.VALID[i];$('explore-coordinate').textContent=`ICRS ${sky.ra_deg.toFixed(6)}°, ${sky.dec_deg.toFixed(6)}° · pixel ${ix}, ${iy} · ${valid?state.arrays.SCI[i].toPrecision(6)+' MJy/sr · λ '+state.arrays.WAVE[i].toFixed(4)+' μm · width '+state.arrays.BAND[i].toFixed(4)+' μm':'masked / unsupported'}`;});for(const event of ['pointerup','pointercancel'])canvas.addEventListener(event,()=>drag=null);canvas.addEventListener('wheel',e=>{if(!state.product)return;e.preventDefault();setZoom(state.zoom*(e.deltaY<0?1.15:1/1.15));},{passive:false});$('explore-plus').onclick=()=>setZoom(state.zoom*1.25);$('explore-minus').onclick=()=>setZoom(state.zoom/1.25);$('explore-reset').onclick=()=>{if(!state.product)return;state.cx=(state.product.shape[1]-1)/2;state.cy=(state.product.shape[0]-1)/2;setZoom(1);};canvas.addEventListener('keydown',e=>{if(state.product&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const [h,w]=state.product.shape;state.cx=Math.max(0,Math.min(w-1,state.cx+({'ArrowLeft':-1,'ArrowRight':1}[e.key]||0)));state.cy=Math.max(0,Math.min(h-1,state.cy+({'ArrowUp':1,'ArrowDown':-1}[e.key]||0)));draw();}if(e.key==='+'||e.key==='='){e.preventDefault();setZoom(state.zoom*1.25);}if(e.key==='-'){e.preventDefault();setZoom(state.zoom/1.25);}});new ResizeObserver(draw).observe(canvas);
for(const key of ['stretch','palette','interpolation'])$('explore-'+key).addEventListener('change',e=>{state.visual=validateVisualization({...state.visual,[key]:e.target.value});render();});$('explore-contrast').addEventListener('input',e=>{state.contrast=Number(e.target.value);render();});
$('export-context').addEventListener('click',()=>{if(!state.product)return;const p=state.product,record={schema_version:'1.0',record_kind:'single_observation_view',field:state.field.id,product_url:state.entry.url,product_sha256:state.entry.sha256,observation:p.observation,region:p.region,wcs:p.wcs,native_shape:p.native_shape,prepared_shape:p.shape,processing:p.processing,array_hashes:Object.fromEntries(Object.entries(p.arrays).map(([k,v])=>[k,v.numeric_sha256])),visualization:state.visual,display:{...p.display,vmax:p.display.vmin+(p.display.vmax-p.display.vmin)/state.contrast},viewport:{zoom:state.zoom,center_x:state.cx,center_y:state.cy},scientific_approval:'PENDING',limitations:p.limitations};const a=make('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}));a.download='SKYSHIFT-'+p.observation.observation_id+'-single-view.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);});
function map(catalog){const svg=$('sky-map'),NS='http://www.w3.org/2000/svg';function add(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text)e.textContent=text;svg.append(e);}for(let dec=-60;dec<=60;dec+=30){const y=25+(90-dec)/180*200;add('line',{x1:45,y1:y,x2:690,y2:y,stroke:'#273b59'});add('text',{x:7,y:y+4,fill:'#97afd2','font-size':10},dec+'°');}for(let ra=0;ra<=360;ra+=60){const x=45+(360-ra)/360*645;add('line',{x1:x,y1:25,x2:x,y2:225,stroke:'#273b59'});add('text',{x:x-10,y:245,fill:'#97afd2','font-size':10},ra+'°');}for(const f of catalog.fields){const x=45+(360-f.ra_deg)/360*645,y=25+(90-f.dec_deg)/180*200;add('circle',{cx:x,cy:y,r:4,fill:'#ed6861'});add('text',{x:x>620?x-13:x+10,y:y<40?y+19:y-9,'text-anchor':x>620?'end':'start',fill:'#e2ebff','font-size':12},f.id==='ngc188'?'NGC 188':f.id.toUpperCase());}}
try{state.catalog=await loadCatalog();galleries(state.catalog,choose);map(state.catalog);choose(new URLSearchParams(location.search).get('field')||'m101');}catch(e){$('explore-title').textContent='The local catalogue could not be opened.';$('explore-error').hidden=false;$('explore-error').textContent=e.message;}
